-- Pale Reach data ported from PR #7948 (VitiumGames). Only rows this PR lacked are added; its own values stay.

-- Bloodpaw Gnoll and the Possessed Statue of the Cardinal are hostile.
UPDATE `creature_template` SET `faction` = 14 WHERE `entry` = 164030;
UPDATE `creature_template` SET `minlevel` = 22, `maxlevel` = 22, `faction` = 14 WHERE `entry` = 164999;

-- CoA World Loot references, cloth, food and recorded drops for 116 Pale Reach creatures, and the quest
-- drops for The Price of Welcome, Enchanted Trinkets, A Hundred Mouths To Feed, Spiritual Incense and the Murloc Spike
-- of the Whimsical Quillscale Murloc.
UPDATE `creature_template` SET `lootid` = `entry`
WHERE `entry` IN (
    164030, 164313, 164356, 164394, 164424, 164430,
    164559, 164598, 164599, 164688, 164997, 164999)
    AND `lootid` = 0;

