-- Food and reagents sold by Ginnad and Kardu in Dun Kazad.
DELETE FROM `npc_vendor` WHERE `entry` IN (164410, 164417);

-- Patrol paths for a Dun Kazad Guard, two Antennasplitter Troggs, a Bonesurper Troll and a Frostmane Soldier.
UPDATE `creature` SET `MovementType` = 2, `wander_distance` = 0
WHERE `guid` IN (9965020, 9965070, 9965088, 9965128, 9965137);

DELETE FROM `creature_addon` WHERE `guid` IN (9965020, 9965070, 9965088, 9965128, 9965137);

DELETE FROM `waypoint_data` WHERE `id` IN (9921102, 9921103, 9921104, 9921106, 9921107);

-- The second Gilded Vale barrier area trigger also credits Magical barrier crossed.
